    FrameworkElement Vortex(){var canvas=new Canvas{Width=520,Height=480,Opacity=.62,IsHitTestVisible=false,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};for(var i=-34;i<=34;i++){var t=i/34d;var upper=new BezierSegment();var lower=new BezierSegment();var figure=new PathFigure{IsClosed=false};figure.Segments.Add(upper);figure.Segments.Add(lower);var path=new System.Windows.Shapes.Path{Data=new PathGeometry(new[]{figure}),Stroke=new SolidColorBrush(Color.FromArgb((byte)(22+Math.Abs(Math.Sin(i*1.63))*46),202,204,229)),StrokeThickness=i%7==0?1.15:.65,SnapsToDevicePixels=true};vortexStrands.Add((path,figure,upper,lower,i,t));canvas.Children.Add(path);}for(var i=0;i<13;i++){var width=170+i*28;var ring=new Ellipse{Width=width,Height=18+i*1.7,Stroke=new SolidColorBrush(Color.FromArgb((byte)(14+i*2),196,197,220)),StrokeThickness=.7,IsHitTestVisible=false};Canvas.SetLeft(ring,(520-width)/2);Canvas.SetTop(ring,394+i*3);canvas.Children.Add(ring);}UpdateVortex(0);return new Viewbox{Stretch=Stretch.UniformToFill,IsHitTestVisible=false,Child=canvas};}
    void UpdateVortex(double phase){foreach(var strand in vortexStrands){var (path,figure,upper,lower,index,spread)=strand;var wave=phase+index*.11;figure.StartPoint=new Point(260+spread*240,0);upper.Point1=new Point(260+spread*205+Math.Sin(wave)*42,70);upper.Point2=new Point(205+Math.Sin(index*.3)*48+Math.Sin(wave-2.1)*52,166);upper.Point3=new Point(260+Math.Sin(index*.41)*16+spread*8+Math.Sin(wave-1)*30,238);lower.Point1=new Point(260+Math.Sin(index*.37)*70+Math.Sin(wave+1.3)*64,302);lower.Point2=new Point(260+spread*170+Math.Sin(wave+2.8)*48,390);lower.Point3=new Point(260+spread*240,480);path.Opacity=.2+.8*(.5+.5*Math.Sin(wave));}}
    static Brush Brush(string c) => new SolidColorBrush(ThemeColors.ColorFrom(c));
}

