        body.Children.Clear(); body.Children.Add(new TextBlock { Text="Welcome back", FontSize=26, FontWeight=FontWeights.SemiBold, Margin=new Thickness(0,0,0,4) }); body.Children.Add(new TextBlock { Text=settings.SpeechMode=="On-device"?"Speak naturally. Voxlet transcribes on this PC and keeps your audio local.":"Speak naturally. Voxlet sends this dictation to the selected cloud provider.", Foreground=B("#A0A4A7"), Margin=new Thickness(0,0,0,22) });
