        var a=Card(panel,true);Grid.SetColumn(a,0);grid.Children.Add(a);var usage=new StackPanel();usage.Children.Add(new TextBlock{Text="Your voice",FontSize=18,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,15)});usage.Children.Add(BigNumber(vault.TotalWords.ToString("N0"),"TOTAL WORDS DICTATED"));usage.Children.Add(Divider());usage.Children.Add(BigNumber(vault.TotalDictations.ToString("N0"),"DICTATIONS"));usage.Children.Add(Divider());usage.Children.Add(BigNumber(RecentWpm(),"AVERAGE SPEAKING SPEED"));usage.Children.Add(new TextBlock{Text="Usage overview begins after 3,000 words.",Foreground=B("#A0A4A7"),FontSize=11,Margin=new Thickness(0,12,0,0)});var b=Card(usage,true);b.Margin=new Thickness(14,0,0,0);Grid.SetColumn(b,1);grid.Children.Add(b);body.Children.Add(grid);
