    ComboBox LanguageCombo(string selected){var combo=new ComboBox{SelectedValuePath="Tag",Height=40};foreach(var language in SpeechLanguages.Whisper.OrderBy(x=>x.Name))combo.Items.Add(new ComboBoxItem{Content=language.Name,Tag=language.Code});combo.SelectedValue=selected;return combo;}
    async Task ChangeLanguage(ComboBox box){if(changingLanguage||box.SelectedValue is not string language)return;if(settings.SpeechMode=="On-device"&&settings.SpeechProvider=="openai-local"&&!await EnsureSelectedWhisperModel(language,settings.AutoDetectLanguage)){changingLanguage=true;box.SelectedValue=settings.SpokenLanguage;changingLanguage=false;return;}settings.SpokenLanguage=language;SettingsStore.Save(settings);}
    string SelectedLocalWhisperPath(string? language=null,bool? auto=null)=>LocalPaths.WhisperModelPath(settings.SpeechModel,language??settings.SpokenLanguage,auto??settings.AutoDetectLanguage);
    bool HasSelectedLocalWhisper(string? language=null,bool? auto=null){var path=SelectedLocalWhisperPath(language,auto);return File.Exists(path)&&(path==LocalPaths.EnglishModel?new FileInfo(path).Length>100_000_000:new FileInfo(path).Length>100_000_000);}
    async Task<bool> EnsureSelectedWhisperModel(string? language=null,bool? auto=null){var path=SelectedLocalWhisperPath(language,auto);if(HasSelectedLocalWhisper(language,auto))return true;if(czechSetupTask is not null)return await czechSetupTask;czechSetupTask=DownloadWhisperModel(path,settings.SpeechModel);try{return await czechSetupTask;}finally{czechSetupTask=null;}}
    async Task<bool> DownloadWhisperModel(string path,string model){var part=path+$".{Environment.ProcessId}.{Guid.NewGuid():N}.download";var id=model=="turbo"?"large-v3-turbo":model;try{Directory.CreateDirectory(Path.GetDirectoryName(path)!);status.Text=$"Downloading Whisper {id}…";using var response=await Http.GetAsync($"https://huggingface.co/ggerganov/whisper.cpp/resolve/main/ggml-{id}.bin",HttpCompletionOption.ResponseHeadersRead);response.EnsureSuccessStatusCode();var total=response.Content.Headers.ContentLength??0;long done=0;var buffer=new byte[1024*1024];await using(var source=await response.Content.ReadAsStreamAsync())await using(var target=new FileStream(part,FileMode.CreateNew,FileAccess.Write,FileShare.None,1024*1024,true)){int n;while((n=await source.ReadAsync(buffer))>0){await target.WriteAsync(buffer.AsMemory(0,n));done+=n;if(total>0)status.Text=$"Downloading Whisper {id}… {done*100/total}%";}await target.FlushAsync();}if(done<50_000_000)throw new InvalidDataException("The model download was incomplete.");File.Move(part,path,true);UpdateEngineLabel();status.Text=$"Whisper {id} installed · ready offline";return true;}catch(Exception ex){try{File.Delete(part);}catch{}status.Text="Speech model not installed · ready to retry";GlassDialog.Show(this,"Could not install the selected Whisper model. Check your internet connection and available disk space.\n\n"+ex.Message,"Model download failed");return false;}}
    static bool HasMultilingualModel()=>File.Exists(LocalPaths.MultilingualModel)&&new FileInfo(LocalPaths.MultilingualModel).Length>=100_000_000;
    void HistoryModern(){body.Children.Clear();var query=SearchBox.Text=="Search notes and transcripts…"?"":SearchBox.Text.Trim();body.Children.Add(SectionIntro(query.Length==0?"Your history":"Search results","Finished dictations, stored on this device."));var entries=vault.History.OrderByDescending(x=>x.Created).Where(x=>query.Length==0||x.Text.Contains(query,StringComparison.OrdinalIgnoreCase)).ToList();if(entries.Count==0)body.Children.Add(Card(new TextBlock{Text=query.Length==0?"No dictations yet.":"No transcripts match your search.",Foreground=B("#A0A4A7")}));foreach(var item in entries)body.Children.Add(TranscriptCard(item,true));var clear=new Button{Content="Delete all history",Style=(Style)FindResource("AppButton"),Margin=new Thickness(0,10,0,0)};clear.Click+=(_,_)=>{if(GlassDialog.Show(this,"Delete all transcript history and reset usage totals?","Confirm deletion",true)){vault.History.Clear();vault.TotalWords=0;vault.TotalDictations=0;VaultStore.Save(vault);HistoryModern();}};body.Children.Add(clear);}
    void Insights(){body.Children.Clear();body.Children.Add(SectionIntro("Insights","Your voice and speaking activity, stored on this device."));var weeks=DateTime.Today.AddDays(-181);weeks=weeks.AddDays(-(int)weeks.DayOfWeek);var byDay=vault.History.GroupBy(x=>x.Created.LocalDateTime.Date).ToDictionary(g=>g.Key,g=>g.Sum(x=>x.WordCount>0?x.WordCount:WordCounter.Count(x.Text)));var activeDays=byDay.Keys.Where(d=>byDay[d]>0).Distinct().OrderByDescending(d=>d).ToArray();var streak=0;for(var d=DateTime.Today;byDay.ContainsKey(d)||d==DateTime.Today&&byDay.ContainsKey(d.AddDays(-1));d=d.AddDays(-1)){if(byDay.ContainsKey(d)){streak++;continue;}if(d==DateTime.Today&&byDay.ContainsKey(d.AddDays(-1))){streak++;continue;}break;}var stats=new UniformGrid{Columns=4,Margin=new Thickness(0,0,0,16)};foreach(var (value,label) in new[]{(vault.TotalWords.ToString("N0"),"WORDS SPOKEN"),(RecentWpm(),"WORDS PER MINUTE"),(vault.TotalDictations.ToString("N0"),"DICTATIONS"),(streak+" day"+(streak==1?"":"s"),"CURRENT STREAK")}){var card=new StackPanel{Margin=new Thickness(14)};card.Children.Add(new TextBlock{Text=value,FontSize=23,FontWeight=FontWeights.SemiBold});card.Children.Add(new TextBlock{Text=label,FontSize=10,Foreground=B("#A0A4A7"),Margin=new Thickness(0,4,0,0)});var shell=new Border{Background=Brushes.Transparent,BorderBrush=(Brush)Application.Current.Resources["GlassPanelEdge"],BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(10),Margin=new Thickness(0,0,10,0),Child=card};stats.Children.Add(shell);}body.Children.Add(stats);var heat=new StackPanel();heat.Children.Add(new TextBlock{Text="Speaking activity",FontSize=17,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,10)});var chart=new Grid{HorizontalAlignment=HorizontalAlignment.Left};for(int w=0;w<26;w++)chart.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(13)});for(int d=0;d<7;d++)chart.RowDefinitions.Add(new RowDefinition{Height=new GridLength(18)});for(int week=0;week<26;week++)for(int day=0;day<7;day++){var date=weeks.AddDays(week*7+day);var count=byDay.GetValueOrDefault(date);var tile=new Border{Width=10,Height=10,CornerRadius=new CornerRadius(2),Background=count==0?new SolidColorBrush(Color.FromArgb(38,255,255,255)):new SolidColorBrush(((SolidColorBrush)Application.Current.Resources["Accent"]).Color),Opacity=count==0?.55:Math.Min(.45+count/35d,.95),ToolTip=$"{date:d} · {count} words",HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};Grid.SetColumn(tile,week);Grid.SetRow(tile,day);chart.Children.Add(tile);}heat.Children.Add(chart);heat.Children.Add(new TextBlock{Text=$"{activeDays.Length} active days · {vault.TotalWords:N0} words spoken",FontSize=11,Foreground=B("#A0A4A7"),Margin=new Thickness(0,10,0,0)});body.Children.Add(Card(heat));var common=vault.History.SelectMany(e=>Regex.Matches(e.Text.ToLowerInvariant(),@"[\p{L}’']+").Select(m=>m.Value)).Where(w=>w.Length>2).GroupBy(w=>w).OrderByDescending(g=>g.Count()).Take(10).ToArray();var list=new StackPanel();list.Children.Add(new TextBlock{Text="Words you say most",FontSize=17,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,10)});foreach(var w in common)list.Children.Add(new TextBlock{Text=$"{w.Key}     {w.Count()} times",Foreground=B("#D6D8D9"),Margin=new Thickness(0,3,0,3)});body.Children.Add(Card(list));}
    void DictionaryPage(bool snippets=false){body.Children.Clear();var header=new DockPanel{Margin=new Thickness(0,0,0,14)};header.Children.Add(new TextBlock{Text=snippets?"Snippets":"Dictionary",FontSize=24,FontWeight=FontWeights.SemiBold});body.Children.Add(header);var tabs=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,0,0,12)};var dictionaryTab=new Button{Content="▣  Dictionary",Style=(Style)FindResource("AppButton"),Margin=new Thickness(0,0,6,0)};dictionaryTab.Click+=(_,_)=>DictionaryPage();var snippetsTab=new Button{Content="▤  Snippets",Style=(Style)FindResource("AppButton")};snippetsTab.Click+=(_,_)=>DictionaryPage(true);tabs.Children.Add(dictionaryTab);tabs.Children.Add(snippetsTab);body.Children.Add(tabs);if(snippets){ShortcutsModern(false);return;}var form=new StackPanel{Visibility=Visibility.Collapsed,Margin=new Thickness(0,0,0,12)};var word=new TextBox{Height=38,ToolTip="Word or phrase",Margin=new Thickness(0,0,0,8)};var variants=new TextBox{Height=42,ToolTip="Alternative pronunciations or spellings (comma separated)"};var add=new Button{Content="Add word",Style=(Style)FindResource("AppButton"),HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,8,0,0)};add.Click+=(_,_)=>{var value=word.Text.Trim();if(value.Length==0)return;vault.CustomDictionary[value]=variants.Text.Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries).ToList();VaultStore.Save(vault);DictionaryPage();};form.Children.Add(word);form.Children.Add(variants);form.Children.Add(add);var addNew=new Button{Content="＋  Add new",Style=(Style)FindResource("AppButton"),HorizontalAlignment=HorizontalAlignment.Right,Padding=new Thickness(13,7,13,7)};addNew.Click+=(_,_)=>{form.Visibility=form.Visibility==Visibility.Visible?Visibility.Collapsed:Visibility.Visible;};DockPanel.SetDock(addNew,Dock.Right);header.Children.Add(addNew);var search=new TextBox{Height=34,ToolTip="Search dictionary",Margin=new Thickness(0,0,0,10)};body.Children.Add(search);body.Children.Add(form);var list=new StackPanel();void Render(){list.Children.Clear();foreach(var entry in vault.CustomDictionary.Where(x=>x.Key.Contains(search.Text,StringComparison.OrdinalIgnoreCase)).OrderBy(x=>x.Key)){var row=new DockPanel{Margin=new Thickness(12,8,12,8)};var remove=new Button{Content="×",Style=(Style)FindResource("AppButton"),Padding=new Thickness(10,3,10,3),VerticalAlignment=VerticalAlignment.Center};remove.Click+=(_,_)=>{vault.CustomDictionary.Remove(entry.Key);VaultStore.Save(vault);Render();};DockPanel.SetDock(remove,Dock.Right);row.Children.Add(remove);var term=new StackPanel();term.Children.Add(new TextBlock{Text=entry.Key,FontWeight=FontWeights.Medium});if(entry.Value.Count>0)term.Children.Add(new TextBlock{Text=string.Join(", ",entry.Value),Foreground=B("#A0A4A7"),Margin=new Thickness(0,3,0,0)});row.Children.Add(term);list.Children.Add(new Border{BorderBrush=new SolidColorBrush(Color.FromArgb(30,255,255,255)),BorderThickness=new Thickness(0,0,0,1),Child=row});}if(list.Children.Count==0)list.Children.Add(new TextBlock{Text=search.Text.Length==0?"Add words like names, tools, and acronyms to improve recognition.":"No matching words.",Foreground=B("#A0A4A7"),Margin=new Thickness(14)});}search.TextChanged+=(_,_)=>Render();Render();body.Children.Add(Card(list));}
