    void ModelsModern(){UpdateEngineLabel();body.Children.Clear();body.Children.Add(SectionIntro("Speech-to-Text","Choose where Voxlet processes your voice and which speech model it uses."));var modes=new StackPanel{Orientation=Orientation.Horizontal};foreach(var mode in new[]{"Cloud","On-device","Enterprise Cloud"}){var b=new Button{Content=mode,Tag=mode,Style=(Style)FindResource("AppButton"),Margin=new Thickness(0,0,8,10)};b.Click+=(_,_)=>{settings.SpeechMode=mode;settings.SpeechProvider=mode switch{"Cloud"=>"openai","Enterprise Cloud"=>"azure",_=>"openai-local"};settings.SpeechModel=mode=="On-device"?"small":mode=="Enterprise Cloud"?"gpt-transcribe":"gpt-4o-mini-transcribe";SettingsStore.Save(settings);ModelsModern();};modes.Children.Add(b);}body.Children.Add(modes);
        var providers=ProviderCatalog.Providers(settings.SpeechMode);if(!providers.Any(x=>x.Id==settings.SpeechProvider)){settings.SpeechProvider=providers[0].Id;settings.SpeechModel=providers[0].Models[0].Id;SettingsStore.Save(settings);}var chips=new WrapPanel{Margin=new Thickness(0,0,0,10)};foreach(var provider in providers){var button=new Button{Content=provider.Name,Tag=provider.Id,Style=(Style)FindResource("AppButton"),Margin=new Thickness(0,0,6,6),Opacity=provider.Id==settings.SpeechProvider?1:.72,IsEnabled=provider.Models.Any(x=>x.Ready)||provider.Id=="openwhispr"};button.ToolTip=button.IsEnabled?provider.Name:"Provider runtime is not included in this Voxlet build yet.";button.Click+=(_,_)=>{settings.SpeechProvider=provider.Id;settings.SpeechModel=provider.Models[0].Id;SettingsStore.Save(settings);ModelsModern();};chips.Children.Add(button);}body.Children.Add(Card(chips));var modelPanel=new StackPanel();modelPanel.Children.Add(new TextBlock{Text="Speech model",FontSize=17,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,7)});foreach(var model in providers.First(x=>x.Id==settings.SpeechProvider).Models){var row=new RadioButton{GroupName="SpeechModels",IsChecked=settings.SpeechModel==model.Id,IsEnabled=model.Ready,Margin=new Thickness(0,5,0,5),Opacity=model.Ready?1:.58,Content=new TextBlock{Text=model.Name+(string.IsNullOrWhiteSpace(model.Detail)?"":"   ·   "+model.Detail),TextWrapping=TextWrapping.Wrap}};row.Checked+=(_,_)=>{settings.SpeechModel=model.Id;SettingsStore.Save(settings);};modelPanel.Children.Add(row);}body.Children.Add(Card(modelPanel));
        if(settings.SpeechMode=="On-device"){var note=new StackPanel();note.Children.Add(new TextBlock{Text="Local model download",FontSize=16,FontWeight=FontWeights.SemiBold});note.Children.Add(new TextBlock{Text=settings.SpeechProvider=="openai-local"?"Whisper models are stored on this device. Downloads are model-specific; large and turbo models need more disk space and memory.":"This provider is shown for the planned model catalog. Its local runtime is not included yet.",Foreground=B("#A0A4A7"),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,5,0,10)});if(settings.SpeechProvider=="openai-local"){var download=new Button{Content="Download / install selected model",Style=(Style)FindResource("AppButton"),HorizontalAlignment=HorizontalAlignment.Left};download.Click+=async(_,_)=>{await EnsureSelectedWhisperModel();ModelsModern();};note.Children.Add(download);}body.Children.Add(Card(note));}
        else if(settings.SpeechProvider=="openwhispr"){var info=new StackPanel();info.Children.Add(new TextBlock{Text="OpenWhispr Cloud uses account sign-in, not an API key. Its published docs describe sign-in inside the OpenWhispr app, but do not document a third-party desktop sign-in or public dictation endpoint. Voxlet will not send audio to an undocumented endpoint.",TextWrapping=TextWrapping.Wrap});var link=new Button{Content="Open OpenWhispr",Style=(Style)FindResource("AppButton"),HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,10,0,0)};link.Click+=(_,_)=>Process.Start(new ProcessStartInfo("https://openwhispr.com"){UseShellExecute=true});info.Children.Add(link);body.Children.Add(Card(info));}
        else if(settings.SpeechProvider=="tinfoil"||settings.SpeechProvider=="assemblyai"&&settings.SpeechModel.Contains("streaming",StringComparison.OrdinalIgnoreCase)||settings.SpeechProvider=="gemini"&&settings.SpeechModel.EndsWith("live",StringComparison.OrdinalIgnoreCase)){body.Children.Add(Card(new TextBlock{Text=ProviderCatalog.Providers(settings.SpeechMode).First(x=>x.Id==settings.SpeechProvider).Models.First(x=>x.Id==settings.SpeechModel).Detail+". Choose a batch transcription model to dictate with the current record-then-transcribe workflow.",TextWrapping=TextWrapping.Wrap,Foreground=B("#A0A4A7")}));}
        else{var config=new StackPanel();config.Children.Add(new TextBlock{Text=settings.SpeechMode=="Enterprise Cloud"?"Azure OpenAI endpoint":"Provider credentials",FontSize=16,FontWeight=FontWeights.SemiBold});if(settings.SpeechProvider=="custom"||settings.SpeechProvider=="azure"){var endpoint=new TextBox{Text=settings.SpeechProvider=="azure"?settings.EnterpriseEndpoint:settings.CustomEndpoint,Height=38,Margin=new Thickness(0,8,0,8)};endpoint.TextChanged+=(_,_)=>{if(settings.SpeechProvider=="azure")settings.EnterpriseEndpoint=endpoint.Text;else settings.CustomEndpoint=endpoint.Text;SettingsStore.Save(settings);};config.Children.Add(new TextBlock{Text="HTTPS endpoint",FontSize=11,Foreground=B("#A0A4A7")});config.Children.Add(endpoint);if(settings.SpeechProvider=="azure"){var deployment=new TextBox{Text=settings.EnterpriseDeployment,Height=38,Margin=new Thickness(0,0,0,8)};deployment.TextChanged+=(_,_)=>{settings.EnterpriseDeployment=deployment.Text;SettingsStore.Save(settings);};config.Children.Add(new TextBlock{Text="Azure deployment name",FontSize=11,Foreground=B("#A0A4A7")});config.Children.Add(deployment);}if(settings.SpeechProvider=="custom"){var customModel=new TextBox{Text=settings.CustomModel,Height=38,Margin=new Thickness(0,0,0,8)};customModel.TextChanged+=(_,_)=>{settings.CustomModel=customModel.Text;SettingsStore.Save(settings);};config.Children.Add(new TextBlock{Text="Model name",FontSize=11,Foreground=B("#A0A4A7")});config.Children.Add(customModel);}}
            if(settings.SpeechProvider=="corti"){var clientId=new TextBox{Text=settings.CortiClientId,Height=38,Margin=new Thickness(0,8,0,8)};clientId.TextChanged+=(_,_)=>{settings.CortiClientId=clientId.Text;SettingsStore.Save(settings);};config.Children.Add(new TextBlock{Text="Corti client ID",FontSize=11,Foreground=B("#A0A4A7")});config.Children.Add(clientId);var tenant=new TextBox{Text=settings.CortiTenant,Height=38,Margin=new Thickness(0,0,0,8)};tenant.TextChanged+=(_,_)=>{settings.CortiTenant=tenant.Text;SettingsStore.Save(settings);};config.Children.Add(new TextBlock{Text="Tenant",FontSize=11,Foreground=B("#A0A4A7")});config.Children.Add(tenant);var env=new ComboBox{ItemsSource=new[]{"eu","us"},SelectedItem=settings.CortiEnvironment,Height=38,Margin=new Thickness(0,0,0,8)};env.SelectionChanged+=(_,_)=>{if(env.SelectedItem is string v){settings.CortiEnvironment=v;SettingsStore.Save(settings);}};config.Children.Add(new TextBlock{Text="Corti environment",FontSize=11,Foreground=B("#A0A4A7")});config.Children.Add(env);}
            if(settings.SpeechProvider!="corti"){var saved=SecretStore.Get((settings.SpeechMode=="Enterprise Cloud"?"enterprise:":"cloud:")+settings.SpeechProvider);config.Children.Add(new TextBlock{Text=saved.Length>0?"API key saved securely on this Windows account. Enter a new value to replace it.":"API key",FontSize=11,Foreground=B("#A0A4A7"),Margin=new Thickness(0,5,0,4)});var key=new PasswordBox{Height=38,Margin=new Thickness(0,0,0,8)};config.Children.Add(key);var save=new Button{Content="Save key securely",Style=(Style)FindResource("AppButton"),HorizontalAlignment=HorizontalAlignment.Left};save.Click+=(_,_)=>{SecretStore.Set((settings.SpeechMode=="Enterprise Cloud"?"enterprise:":"cloud:")+settings.SpeechProvider,key.Password);key.Clear();ModelsModern();};config.Children.Add(save);}else{var saved=SecretStore.Get("corti-client-secret");config.Children.Add(new TextBlock{Text=saved.Length>0?"Client secret saved securely on this Windows account.":"Corti client secret",FontSize=11,Foreground=B("#A0A4A7"),Margin=new Thickness(0,5,0,4)});var secret=new PasswordBox{Height=38,Margin=new Thickness(0,0,0,8)};config.Children.Add(secret);var save=new Button{Content="Save credentials securely",Style=(Style)FindResource("AppButton"),HorizontalAlignment=HorizontalAlignment.Left};save.Click+=(_,_)=>{SecretStore.Set("corti-client-secret",secret.Password);secret.Clear();ModelsModern();};config.Children.Add(save);}config.Children.Add(new TextBlock{Text="Cloud mode uploads this dictation audio to the selected provider. Your Windows DPAPI-encrypted key stays on this device. Provider pricing and retention policies apply.",Foreground=B("#A0A4A7"),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,0)});body.Children.Add(Card(config));}
