    string RecentWpm(){var items=vault.History.Where(e=>e.SpeakingWpm>0).TakeLast(10).ToArray();return items.Length==0?"— WPM":$"{items.Average(e=>e.SpeakingWpm):0} WPM";}
    Border SectionIntro(string title,string description){var panel=new StackPanel();panel.Children.Add(new TextBlock{Text=title,FontSize=24,FontWeight=FontWeights.SemiBold});panel.Children.Add(new TextBlock{Text=description,Foreground=B("#A0A4A7"),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,5,0,18)});return new Border{Child=panel};}
    Border Card(UIElement child,bool featured=false){var layers=new Grid();var sample=new Border{CornerRadius=new CornerRadius(16),Opacity=1,IsHitTestVisible=false};layers.Children.Add(sample);layers.Children.Add(new Border{Background=(Brush)Application.Current.Resources["GlassPanelSheen"],CornerRadius=new CornerRadius(16),Height=featured?10:7,VerticalAlignment=VerticalAlignment.Top,IsHitTestVisible=false});layers.Children.Add(new Border{Child=child,Margin=new Thickness(18)});var card=new Border{Background=Brushes.Transparent,BorderBrush=(Brush)Application.Current.Resources["GlassPanelEdge"],BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(16),Padding=new Thickness(0),Margin=new Thickness(0,0,0,12),Child=layers,Effect=new DropShadowEffect{Color=Color.FromArgb(60,8,12,24),BlurRadius=featured?22:12,ShadowDepth=featured?7:3,Opacity=.45,RenderingBias=RenderingBias.Performance}};AttachGlass(card,sample,featured?13:7);card.Unloaded+=(_,_)=>glassSurfaces.RemoveAll(x=>ReferenceEquals(x.Surface,card));return card;}
    void AttachGlass(Border surface,Border sample,double blur){if(settingsWindow is not null){sample.Background=new SolidColorBrush(Color.FromArgb(206,22,24,36));return;}var backdrop=ThemeBackdrop;var brush=new VisualBrush(backdrop){Stretch=Stretch.Fill,ViewboxUnits=BrushMappingMode.Absolute,ViewportUnits=BrushMappingMode.Absolute};sample.Background=brush;if(blur>5)sample.Effect=new BlurEffect{Radius=blur,RenderingBias=RenderingBias.Performance};glassSurfaces.Add((surface,sample,brush,backdrop));void update(){if(!surface.IsLoaded||surface.ActualWidth<1||surface.ActualHeight<1)return;try{var r=surface.TransformToVisual(backdrop).TransformBounds(new Rect(0,0,surface.ActualWidth,surface.ActualHeight));brush.Viewbox=new Rect(r.X+5,r.Y+5,Math.Max(1,r.Width-10),Math.Max(1,r.Height-10));brush.Viewport=new Rect(0,0,surface.ActualWidth,surface.ActualHeight);}catch{}}surface.Loaded+=(_,_)=>Dispatcher.BeginInvoke(update,DispatcherPriority.Loaded);surface.SizeChanged+=(_,_)=>Dispatcher.BeginInvoke(update,DispatcherPriority.Render);}
    void MainScroll_ScrollChanged(object sender,ScrollChangedEventArgs e){foreach(var item in glassSurfaces)if(item.Surface.IsLoaded)try{var r=item.Surface.TransformToVisual(item.Backdrop).TransformBounds(new Rect(0,0,item.Surface.ActualWidth,item.Surface.ActualHeight));item.Brush.Viewbox=new Rect(r.X+5,r.Y+5,Math.Max(1,r.Width-10),Math.Max(1,r.Height-10));item.Brush.Viewport=new Rect(0,0,item.Surface.ActualWidth,item.Surface.ActualHeight);}catch{}}
    Border Divider()=>new(){Height=1,Background=B("#343637"),Margin=new Thickness(0,13,0,13)};
    StackPanel BigNumber(string number,string title){var panel=new StackPanel();panel.Children.Add(new TextBlock{Text=number,FontSize=24,FontWeight=FontWeights.SemiBold});panel.Children.Add(new TextBlock{Text=title,FontSize=10,Foreground=B("#A0A4A7"),Margin=new Thickness(0,3,0,0)});return panel;}
    Border TranscriptCard(TranscriptEntry entry,bool copy){var row=new DockPanel();if(copy){var button=new Button{Content="Copy",Style=(Style)FindResource("AppButton"),Padding=new Thickness(12,6,12,6),VerticalAlignment=VerticalAlignment.Top};button.Click+=(_,_)=>Clipboard.SetText(entry.Text);DockPanel.SetDock(button,Dock.Right);row.Children.Add(button);}var text=new StackPanel();text.Children.Add(new TextBlock{Text=$"{entry.Created:g}  ·  {entry.Language}  ·  {entry.DurationSeconds:0}s  ·  {entry.SpeakingWpm:0} WPM",FontSize=10,Foreground=B("#A0A4A7")});text.Children.Add(new TextBlock{Text=entry.Text,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,12,0),Foreground=B("#E4E5E6")});row.Children.Add(text);return Card(row);}
    void LoadMics() { micBox.Items.Clear(); micBox.Items.Add(new MicChoice("Windows default microphone", -1)); for(int i=0;i<WaveIn.DeviceCount;i++){var cap=WaveIn.GetCapabilities(i);micBox.Items.Add(new MicChoice(cap.ProductName,i));} var selected=Enumerable.Range(0,micBox.Items.Count).Select(i=>micBox.Items[i]).OfType<MicChoice>().FirstOrDefault(x=>x.Index.ToString()==settings.MicrophoneId)??(MicChoice)micBox.Items[0]; micBox.SelectedItem=selected; micBox.SelectionChanged += (_,_) => { if(micBox.SelectedItem is MicChoice c){settings.MicrophoneId=c.Index.ToString();SettingsStore.Save(settings);} }; }
    void History(){HistoryModern();}
    void Shortcuts() { body.Children.Clear(); body.Margin=new Thickness(24); body.Children.Add(Card("Spoken shortcuts", "Create a phrase you dictate and the text it expands to. This preview stores shortcuts locally; matching shortcuts is not yet connected to transcription.")); var phrase=new TextBox{Height=34,Margin=new Thickness(0,10,0,8),ToolTip="Spoken phrase"};var expansion=new TextBox{Height=34,Margin=new Thickness(0,0,0,8),ToolTip="Expansion"};body.Children.Add(phrase);body.Children.Add(expansion);var add=new Button{Content="Add shortcut",Padding=new Thickness(14,8,14,8)};add.Click+=(_,_)=>{if(!string.IsNullOrWhiteSpace(phrase.Text)&&!string.IsNullOrWhiteSpace(expansion.Text)){vault.Shortcuts.Add(new(){Phrase=phrase.Text.Trim(),Expansion=expansion.Text});VaultStore.Save(vault);Shortcuts();}};body.Children.Add(add);foreach(var s in vault.Shortcuts)body.Children.Add(Card(s.Phrase,"→ "+s.Expansion)); }
    void SettingsPage() { body.Children.Clear();body.Margin=new Thickness(24);body.Children.Add(Card("Settings",$"Dictation key: {settings.Trigger}\nTheme is selected from the top menu. English model: small.en, about 465 MB."));var key=new Button{Content="Change dictation key…",Padding=new Thickness(14,8,14,8)};key.Click+=(_,_)=>{var w=new KeyCaptureWindow(settings.Theme);if(w.ShowDialog()==true){settings.Trigger=w.Selected;SettingsStore.Save(settings);trigger?.Dispose();trigger=new GlobalTrigger(settings.Trigger,Dispatcher,TriggerDown,TriggerUp);pill.RefreshLabel();SettingsPage();}};body.Children.Add(key);var learn=new CheckBox{Content="Automatically learn words I correct (preview setting)",IsChecked=settings.AutoLearn,Margin=new Thickness(0,12,0,0)};learn.Checked+=(_,_)=>{settings.AutoLearn=true;SettingsStore.Save(settings);};learn.Unchecked+=(_,_)=>{settings.AutoLearn=false;SettingsStore.Save(settings);};body.Children.Add(learn); body.Children.Add(Card("Privacy", "No audio is kept after transcription. Temporary WAV audio is deleted after processing. Transcript history is encrypted with Windows DPAPI. No telemetry or network requests are made.")); }
    Border Card(string title,string detail){var stack=new StackPanel();stack.Children.Add(new TextBlock{Text=title,FontSize=17,FontWeight=FontWeights.SemiBold});stack.Children.Add(new TextBlock{Text=detail,TextWrapping=TextWrapping.Wrap,Foreground=(Brush)Application.Current.Resources["MutedText"],Margin=new Thickness(0,6,0,0)});var sample=new Border{CornerRadius=new CornerRadius(16),IsHitTestVisible=false};var layers=new Grid();layers.Children.Add(sample);layers.Children.Add(new Border{Child=stack,Margin=new Thickness(18)});var card=new Border{Background=Brushes.Transparent,BorderBrush=(Brush)Application.Current.Resources["GlassPanelEdge"],BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(16),Margin=new Thickness(0,0,0,12),Child=layers};AttachGlass(card,sample,8);return card;}
