static class FogMotion
{
 public static RadialGradientBrush Brush(string hex,byte alpha){var color=ThemeColors.ColorFrom(hex);return new RadialGradientBrush(new GradientStopCollection{new(Color.FromArgb(alpha,color.R,color.G,color.B),0),new(Color.FromArgb((byte)(alpha*.44),color.R,color.G,color.B),.42),new(Color.FromArgb(0,color.R,color.G,color.B),1)});}
 public static void Set(Panel layer,bool running,double scale){foreach(var ellipse in layer.Children.OfType<Ellipse>()){if(ellipse.RenderTransform is TranslateTransform old){old.BeginAnimation(TranslateTransform.XProperty,null);old.BeginAnimation(TranslateTransform.YProperty,null);}if(!running||!SystemParameters.ClientAreaAnimation){ellipse.RenderTransform=Transform.Identity;continue;}var motion=new TranslateTransform();ellipse.RenderTransform=motion;var i=layer.Children.IndexOf(ellipse);var ease=new SineEase{EasingMode=EasingMode.EaseInOut};motion.BeginAnimation(TranslateTransform.XProperty,new DoubleAnimation((i%2==0?-1:1)*24*scale,(i%2==0?1:-1)*24*scale,TimeSpan.FromSeconds(48+i*11)){AutoReverse=true,RepeatBehavior=RepeatBehavior.Forever,EasingFunction=ease});motion.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation((i%2==0?1:-1)*16*scale,(i%2==0?-1:1)*16*scale,TimeSpan.FromSeconds(61+i*9)){AutoReverse=true,RepeatBehavior=RepeatBehavior.Forever,EasingFunction=ease});}}
}






















